INSERT INTO `ai_chat_role` VALUES (10,NULL,11,'通用 AI 助手','http://127.0.0.1:48080/admin-api/infra/file/4/get/20260821/ScreenShot_2026-01-05_143317_648.png','助手',1,'默认角色','您好，我是您的AI智能助手，我会尽力回答您的问题或提供有用的建议！！！！',NULL,NULL,NULL,0x01,0,'1','2024-05-13 20:44:48','1','2026-08-21 14:04:28',0x00,1),(11,NULL,64,'Python 专家','http://127.0.0.1:48080/admin-api/infra/file/4/get/20260821/ScreenShot_2026-01-05_143417_287.png','编程开发',2,'Python','我希望你能作为一名 python 专家。我将向你提供有关我的技术问题的所有信息，而你的角色是解决我的问题。你应该用你的计算机科学、网络基础设施和 IT 安全知识来解决我的问题。在你的回答中，使用聪明的、简单的、为各种层次的人所理解的语言会有帮助。逐步解释你的解决方案并使用要点是很有帮助的。尽量避免过多的技术细节，但在必要时使用它们。我希望你用解决方案来回答，而不是写任何解释。','6','17,18,19','filesystem',0x01,0,'1','2024-05-17 23:23:20','1','2026-08-21 14:04:53',0x00,1),(12,1,NULL,'小可爱角色','http://test.txgy.xianoupeng.cn/5752750225f522ba794b16ad0b0e73d268093760546ebc2519b1a5dfc5b064d1.jpg',NULL,0,'卡比兽，爱睡觉','你好，我是宠物小精灵大师！',NULL,NULL,NULL,0x00,0,'1','2024-05-25 13:25:46','1','2026-08-21 12:27:29',0x00,1),(13,NULL,17,'写作助手','http://test.txgy.xianoupeng.cn/2a124ba5743f9572fcbd2718a64ba599618c96ddba6c7391ad35906cd3f37f94.png','写作',10,'一个厉害的写手高手','你是一个非常会写作的人！',NULL,NULL,NULL,0x01,0,'1','2024-07-10 22:55:58','1','2026-08-21 14:04:57',0x01,1),(14,NULL,17,'导图助手','http://test.txgy.xianoupeng.cn/7401c394a43280732e6aaa715fbfefadc33eeb8fab8f45f6b53f1acf6b22ae29.png','写作',11,'一个厉害的思维大师！','你是一位非常优秀的思维导图助手，你会把用户的所有提问都总结成思维导图，然后以 Markdown 格式输出。markdown 只需要输出一级标题，二级标题，三级标题，四级标题，最多输出四级，除此之外不要输出任何其他 markdown 标记。下面是一个合格的例子：\n             # Geek-AI 助手\n             ## 完整的开源系统\n             ### 前端开源\n             ### 后端开源\n             ## 支持各种大模型\n             ### OpenAI\n             ### Azure\n             ### 文心一言\n             ### 通义千问\n             ## 集成多种收费方式\n             ### 支付宝\n             ### 微信\n            除此之外不要任何解释性语句。',NULL,NULL,NULL,0x01,0,'1','2024-07-29 21:47:20','1','2026-08-21 14:05:17',0x01,1),(15,NULL,26,'测试知识库','http://test.txgy.xianoupeng.cn/d3a7656aae53c8f063d4578c7a65f9045ef25420ff32cc32dd121a60abcf9127.png','助手',10,'我只是个小助手','一个问答助手','3',NULL,NULL,0x01,0,'1','2025-03-09 17:35:36','1','2026-08-21 12:27:29',0x01,1),(16,1,21,'测试知识库','http://test.txgy.xianoupeng.cn/a2cfbf52d157911ecfb29c4a26b4a19247f6bb2c97a5104c46c970fc235880ef.png','助手',0,'测试一下','一个小助手','2',NULL,NULL,0x00,0,'1','2025-03-09 18:33:01','1','2026-08-21 12:27:29',0x00,1),(17,1,NULL,'一个可以查询天气的小助手','http://test.txgy.xianoupeng.cn/de74fdbe9ad40173345d4cd1e2b684fcbb5e797f7b7cc37b42dcbaa20dcf6bb3.png',NULL,0,'查查查天气','天气小助手','','18,17,19',NULL,0x00,0,'1','2025-03-14 20:03:27','1','2026-08-21 12:27:29',0x00,1),(18,1,NULL,'测试 mcp 角色','http://test.txgy.xianoupeng.cn/20250826/1756026082_1756187441425.png',NULL,0,'aa','bb','','21',NULL,0x00,0,'1','2025-08-26 13:50:48','1','2026-08-21 12:27:29',0x00,1),(19,1,NULL,'MCP Client 案例','http://test.txgy.xianoupeng.cn/20250828/微信图片_2025-06-22_204705_590_1756386389963.png',NULL,0,'MCP Client 案例','一个帅气的案例','','','filesystem',0x00,0,'1','2025-08-28 21:06:46','1','2026-08-21 12:27:29',0x00,1);
