--
-- Table structure for table `ai_music`
--

DROP TABLE IF EXISTS `ai_music`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_music` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '音乐名称',
  `lyric` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '歌词',
  `image_url` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `audio_url` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '音频地址',
  `video_url` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '视频地址',
  `status` tinyint NOT NULL COMMENT '音乐状态',
  `description` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述词',
  `prompt` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提示词',
  `platform` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型平台',
  `model_id` bigint NOT NULL COMMENT '模型编号',
  `model` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型',
  `generate_mode` tinyint NOT NULL COMMENT '生成模式',
  `tags` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '音乐风格标签',
  `duration` double DEFAULT NULL COMMENT '音乐时长',
  `public_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否发布',
  `task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务编号',
  `error_message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 音乐表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ai_music`
--

LOCK TABLES `ai_music` WRITE;
/*!40000 ALTER TABLE `ai_music` DISABLE KEYS */;
INSERT INTO `ai_music` VALUES (1,1,'幸福的旋律','[Verse]\n阳光撒满了街道\n梦想在心中起跑\n[Verse 2]\n快乐随着风在笑\n青春在时光里跳\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好\n[Verse 3]\n花开在晨曦微笑\n心跳伴随音符跳\n[Bridge]\n让烦恼都退烧\n世界只剩心跳\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好','https://cdn1.suno.ai/image_73032eee-470e-46ff-a9bd-abb3e67b2934.png','http://test.txgy.xianoupeng.cn/12f3702f71bf3d1e7eadbc0d611afca58868b783fe9c8b30bf913b4aa74e3af1.mp3','https://cdn1.suno.ai/73032eee-470e-46ff-a9bd-abb3e67b2934.mp4',20,'来一首快乐的歌曲','[Verse]\n阳光撒满了街道\n梦想在心中起跑\n\n[Verse 2]\n快乐随着风在笑\n青春在时光里跳\n\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好\n\n[Verse 3]\n花开在晨曦微笑\n心跳伴随音符跳\n\n[Bridge]\n让烦恼都退烧\n世界只剩心跳\n\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好','Suno',0,'chirp-v3.5',2,'[\"pop\"]',145.96,0x00,'73032eee-470e-46ff-a9bd-abb3e67b2934',NULL,'1','2024-06-27 21:08:42','1','2026-08-21 12:27:30',0x00,1),(2,1,'幸福的旋律','[Verse]\n阳光撒满了街道\n梦想在心中起跑\n[Verse 2]\n快乐随着风在笑\n青春在时光里跳\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好\n[Verse 3]\n花开在晨曦微笑\n心跳伴随音符跳\n[Bridge]\n让烦恼都退烧\n世界只剩心跳\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好','http://test.txgy.xianoupeng.cn/e8e50a3fd176756069c7cd2117d32b3eddec58c2439d1e8faf8f08d23a7fd992.png','https://cdn1.suno.ai/727a5f9b-102d-438a-909a-13f31c433dbb.mp3','http://test.txgy.xianoupeng.cn/bb48fe2b19211d80f3522b2528b12dad6f72a95c674cff4a6b8c0396ed954a4b.mp4',20,'来一首快乐的歌曲','[Verse]\n阳光撒满了街道\n梦想在心中起跑\n\n[Verse 2]\n快乐随着风在笑\n青春在时光里跳\n\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好\n\n[Verse 3]\n花开在晨曦微笑\n心跳伴随音符跳\n\n[Bridge]\n让烦恼都退烧\n世界只剩心跳\n\n[Chorus]\n哼着熟悉的歌谣\n幸福就在我怀抱\n奔向未来的征兆\n一起创造美好','Suno',0,'chirp-v3.5',2,'[\"pop\"]',121.48,0x00,'727a5f9b-102d-438a-909a-13f31c433dbb',NULL,'1','2024-06-27 21:08:42','1','2026-08-21 12:27:30',0x00,1),(3,1,'快乐的时光','[Verse]\n阳光洒在天空下\n笑脸藏不住啊\n[Verse 2]\n伙伴们聚在一起\n欢笑声不停歇\n[Chorus]\n快乐就在眼前\n一起尽情欢笑\n跳舞不停的旋转\n快乐围绕着我们\n[Verse 3]\n时间在快乐中飞\n烦恼都忘掉了\n[Bridge]\n闭上眼用心感觉\n幸福在心中荡漾\n[Chorus]\n快乐就在眼前\n一起尽情欢笑\n跳舞不停的旋转\n快乐围绕着我们','https://cdn1.suno.ai/image_c300a71d-237d-4d82-a884-00ccab42f10e.png