--
-- Table structure for table `im_friend_request`
--

DROP TABLE IF EXISTS `im_friend_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_friend_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `from_user_id` bigint NOT NULL COMMENT '发起方用户编号',
  `to_user_id` bigint NOT NULL COMMENT '接收方用户编号',
  `handle_result` tinyint NOT NULL DEFAULT '0' COMMENT '处理结果；0未处理；1同意；2拒绝',
  `apply_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请理由（发起方填写）',
  `handle_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理理由（接收方拒绝时可选填）',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发起方对接收方的备注；同意后写入 A 侧 im_friend.display_name',
