--
-- Table structure for table `im_group_request`
--

DROP TABLE IF EXISTS `im_group_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_group_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `group_id` bigint NOT NULL COMMENT '群编号',
  `user_id` bigint NOT NULL COMMENT '申请人 / 被邀请人用户编号',
  `inviter_user_id` bigint DEFAULT NULL COMMENT '邀请人用户编号；NULL=主动申请；非NULL=被邀请待审批',
  `apply_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '申请理由',
  `add_source` tinyint DEFAULT NULL COMMENT '加入来源；参见 ImGroupAddSourceEnum',
  `handle_result` tinyint NOT NULL DEFAULT '0' COMMENT '处理结果；0未处理 1同意 2拒绝',
  `handle_user_id` bigint DEFAULT NULL COMMENT '处理人用户编号',
  `handle_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '处理理由',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_group_request` (`group_id`,`user_id`,`tenant_id`) USING BTREE,
  KEY `idx_group_handle` (`group_id`,`handle_result`) USING BTREE,
  KEY `idx_user` (`user_id`,`id`) USING BTREE,
  KEY `idx_sync` (`group_id`,`update_time`,`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IM 加群申请记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

